OI.ESCROW_STATUS, OI.LEVEL_ID, OI.LEVEL_NAME, OI.USER_LEVEL_DISCOUNT_RATE, OI.USER_LEVEL_DISCOUNT_PRICE, OI.CAMPAIGN_CODE,
