	/* saleson.shop.order.OrderMapper.deleteOrderPaymentBuyTempForBatch */
    DELETE FROM OP_ORDER_PAYMENT_BUY_TEMP
    WHERE DATEDIFF(CURRENT_DATE, DATE_FORMAT(CREATED_DATE,'%Y-%m-%d')) > #{retentionPeriod}

	/* saleson.shop.order.OrderMapper.deleteOrderTempForBatch */
    DELETE FROM OP_ORDER_TEMP
    WHERE DATEDIFF(CURRENT_DATE, DATE_FORMAT(CREATED_DATE,'%Y-%m-%d')) > #{retentionPeriod}

	/* saleson.shop.order.OrderMapper.deleteOrderItemBuyTempForBatch */
    DELETE FROM OP_ORDER_ITEM_BUY_TEMP
    WHERE DATEDIFF(CURRENT_DATE, DATE_FORMAT(CREATED_DATE,'%Y-%m-%d')) > #{retentionPeriod}

	/* saleson.shop.order.OrderMapper.deleteOrderShippingBuyTempForBatch */
    DELETE FROM OP_ORDER_SHIPPING_BUY_TEMP
    WHERE DATEDIFF(CURRENT_DATE, DATE_FORMAT(CREATED_DATE,'%Y-%m-%d')) > #{retentionPeriod}

