/* saleson.shop.order.OrderMapper.getOrderItemCntForMyPage */
SELECT COUNT(*)
FROM
(
	SELECT order_code
	FROM OP_ORDER_ITEM
	WHERE	USER_ID = #{value}
) a
INNER JOIN OP_ORDER_SHIPPING_INFO b ON a.order_code = b.order_code

/* saleson.shop.order.OrderMapper.getOrderItemClaimCntForMyPage */
SELECT COUNT(*)
FROM
(
	SELECT order_code
	FROM OP_ORDER_ITEM
	WHERE	USER_ID = #{value}
		AND ORDER_STATUS  >=  50
) a
INNER JOIN OP_ORDER_SHIPPING_INFO b ON a.order_code = b.order_code

